import type { HTMLAttributes } from 'react';
import { cx } from '@/utils/cx';

export type BadgeColor = 'primary' | 'neutral' | 'new';
export type BadgeProps = Omit<HTMLAttributes<HTMLSpanElement>, 'color'> & { color?: BadgeColor; variant?: 'count' | 'label' | 'pill' | 'subtle' | 'index' };

export function Badge({ color = 'neutral', variant = 'count', className, ...props }: BadgeProps) {
  return <span data-color={color} data-variant={variant} className={cx('ui-badge', className)} {...props} />;
}

import type { AnchorHTMLAttributes, ElementType, ReactNode } from 'react';
import type { IconComponent } from '@/components/foundations/icon-types';
import { buttonClassNames, buttonIconClassNames, type ButtonSize, type ButtonVariant } from './button';

export type ButtonLinkProps = AnchorHTMLAttributes<HTMLAnchorElement> & {
  as?: ElementType;
  children: ReactNode;
  variant?: ButtonVariant;
  size?: ButtonSize;
  leadingIcon?: IconComponent;
  trailingIcon?: IconComponent;
};

/** Anchor semantics and the same presentation as Button. Router adapters are optional. */
export function ButtonLink({ as: Component = 'a', children, variant = 'secondary', size = 'medium', leadingIcon: LeadingIcon, trailingIcon: TrailingIcon, className, ...props }: ButtonLinkProps) {
  return <Component {...props} className={buttonClassNames(size, false, className)} data-variant={variant} data-size={size}>
    {LeadingIcon && <LeadingIcon className={buttonIconClassNames[size]} aria-hidden />}
    <span className="ui-button__label">{children}</span>
    {TrailingIcon && <TrailingIcon className={buttonIconClassNames[size]} aria-hidden />}
  </Component>;
}

'use client';

import type { ButtonHTMLAttributes, ReactNode, Ref } from 'react';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';
import { Spinner } from '@/components/base/spinner/spinner';

export type ButtonVariant = 'primary' | 'secondary' | 'ghost' | 'danger' | 'soft' | 'outline' | 'solid' | 'quiet';
export type ButtonSize = 'medium' | 'small' | 'xs';

type NativeButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children'>;
type ContentProps =
  | { iconOnly: true; 'aria-label': string; leadingIcon: IconComponent; children?: never }
  | { iconOnly?: false; children: ReactNode; leadingIcon?: IconComponent };

export type ButtonProps = NativeButtonProps & ContentProps & {
  variant?: ButtonVariant;
  size?: ButtonSize;
  trailingIcon?: IconComponent;
  isLoading?: boolean;
  loadingLabel?: string;
  ref?: Ref<HTMLButtonElement>;
};

const base = 'ui-button inline-flex shrink-0 items-center justify-center whitespace-nowrap select-none outline-none';
const sizes: Record<ButtonSize, string> = {
  medium: 'h-9 rounded-[10px] px-2 gap-0.5',
  small: 'h-8 rounded-lg px-2 gap-0.5',
  xs: 'h-6 rounded-[5px] px-2 gap-0.5',
};
export const buttonIconClassNames: Record<ButtonSize, string> = { medium: 'size-5', small: 'size-[18px]', xs: 'size-3.5' };
export function buttonClassNames(size: ButtonSize, iconOnly = false, className?: string) {
  return cx(base, sizes[size], iconOnly && 'ui-button--icon-only !p-0', className);
}

export function Button({
  variant = 'primary',
  size = 'medium',
  iconOnly = false,
  leadingIcon: LeadingIcon,
  trailingIcon: TrailingIcon,
  children,
  className,
  type = 'button',
  isLoading = false,
  loadingLabel,
  disabled,
  onClick,
  onKeyDown,
  ...props
}: ButtonProps) {
  return (
    <button
      {...props}
      type={isLoading && type === 'submit' ? 'button' : type}
      disabled={disabled}
      aria-disabled={isLoading || props['aria-disabled'] || undefined}
      aria-busy={isLoading || undefined}
      aria-description={isLoading && loadingLabel ? loadingLabel : props['aria-description']}
      data-variant={variant}
      data-size={size}
      data-icon-only={iconOnly || undefined}
      data-loading={isLoading || undefined}
      data-loading-label={loadingLabel !== undefined || undefined}
      className={buttonClassNames(size, iconOnly, className)}
      onClick={event => { if (isLoading || props['aria-disabled'] === true || props['aria-disabled'] === 'true') { event.preventDefault(); event.stopPropagation(); return; } onClick?.(event); }}
      onKeyDown={event => { if (isLoading && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); event.stopPropagation(); return; } onKeyDown?.(event); }}
    >
      {LeadingIcon && <span className="ui-button__leading-slot" aria-hidden><LeadingIcon className={cx(buttonIconClassNames[size], 'ui-button__leading-icon')}/></span>}
      {!iconOnly && <span className="ui-button__label">{children}</span>}
      {!iconOnly && TrailingIcon && <TrailingIcon className={buttonIconClassNames[size]} aria-hidden />}
      <Spinner className="ui-button__busy-spinner" size={size === 'xs' ? 'xs' : size === 'small' ? 'sm' : 'md'}/>
    </button>
  );
}

import type { HTMLAttributes, ReactNode } from 'react';
import { cx } from '@/utils/cx';

export type CollapsibleProps = Omit<HTMLAttributes<HTMLDivElement>, 'children'> & { isOpen: boolean; children: ReactNode };

/** Keep descendants mounted while hiding their focus targets and animating flow. */
export function Collapsible({ isOpen, children, className, ...props }: CollapsibleProps) {
  return <div {...props} className={cx('ui-collapsible', className)} data-open={isOpen || undefined} aria-hidden={!isOpen} inert={!isOpen}>
    <div className="ui-collapsible__inner"><div className="ui-collapsible__content">{children}</div></div>
  </div>;
}

'use client';

import { cloneElement, useContext, useId, useRef, useState, type ComponentProps, type KeyboardEvent, type ReactNode, type Ref, type RefObject } from 'react';
import { Focusable, OverlayArrow, OverlayTriggerStateContext, Popover, PreviewTrigger, type PopoverProps } from 'react-aria-components';
import { cx } from '@/utils/cx';

export type HoverCardProps = {
  trigger: ComponentProps<typeof Focusable>['children'];
  children: ReactNode;
  title?: string;
  label?: string;
  placement?: PopoverProps['placement'];
  delay?: number;
  closeDelay?: number;
  isDisabled?: boolean;
  showArrow?: boolean;
  className?: string;
};

/** A non-modal preview: hover keeps page focus; Tab can enter its controls. */
function PointerTrigger({trigger,isDisabled,triggerRef,suppressRestore}:{trigger:HoverCardProps['trigger'];isDisabled?:boolean;triggerRef:Ref<HTMLElement>;suppressRestore:RefObject<boolean>}) {
  const state = useContext(OverlayTriggerStateContext);
  const element = trigger;
  // A first hover can precede a pointer press. Use the public trigger state so
  // it keeps the configured warmup, safe area and focus behavior without
  // changing the page's keyboard modality.
  const pointerTrigger = cloneElement(element,{onPointerEnter:event=>{
    element.props.onPointerEnter?.(event);
    if(!isDisabled&&!event.defaultPrevented&&(event.pointerType==='mouse'||event.pointerType==='pen')&&!state?.isOpen)state?.open();
  },onFocusCapture:event=>{
    element.props.onFocusCapture?.(event);
    if(suppressRestore.current){suppressRestore.current=false;event.stopPropagation();element.props.onFocus?.(event);}
  }}) as HoverCardProps['trigger'];
  return <Focusable ref={triggerRef}>{pointerTrigger}</Focusable>;
}

function PreviewContent({children,title,titleId,label,isExiting,onDismiss}:{children:ReactNode;title?:string;titleId:string;label:string;isExiting:boolean;onDismiss:()=>void}) {
  const state = useContext(OverlayTriggerStateContext);
  function handleKeyDown(event:KeyboardEvent<HTMLElement>) {
    if(event.key!=='Escape'||event.defaultPrevented)return;
    // Keep the public preview state's cooldown and cancellation bookkeeping,
    // then close the controlled surface immediately for explicit dismissal.
    state?.close();
    onDismiss();
  }
  return <section onKeyDown={handleKeyDown} inert={isExiting} aria-hidden={isExiting || undefined} className="ui-popover__dialog" role="region" aria-labelledby={title ? titleId : undefined} aria-label={title ? undefined : label}>
    {title && <header className="ui-popover__header"><h3 id={titleId}>{title}</h3></header>}<div className="ui-popover__body">{children}</div>
  </section>;
}

export function HoverCard({ trigger, children, title, label = 'Preview details', placement = 'top', delay = 400, closeDelay = 180, isDisabled, showArrow = true, className }: HoverCardProps) {
  const titleId = useId();
  const triggerRef = useRef<HTMLElement>(null);
  const suppressRestore = useRef(false);
  const [open, setOpen] = useState(false);
  function dismiss() {
    // Pointer travel keeps its close delay; an explicit dismissal starts the
    // exit immediately so Tab cannot return to the outgoing preview.
    setOpen(false);
    suppressRestore.current=true;
    triggerRef.current?.focus({preventScroll:true});
  }
  return <PreviewTrigger isOpen={open} onOpenChange={setOpen} delay={delay} closeDelay={closeDelay} isDisabled={isDisabled}>
    <PointerTrigger trigger={trigger} isDisabled={isDisabled} triggerRef={triggerRef} suppressRestore={suppressRestore}/>
    <Popover shouldSkipAnimation={false} placement={placement} offset={showArrow ? 10 : 6} aria-labelledby={title ? titleId : undefined} aria-label={title ? undefined : label} className={cx('ui-popover ui-hover-card', className)}>
      {({isExiting})=><>
      {showArrow && <OverlayArrow className="ui-popover__arrow"><svg width="12" height="8" viewBox="0 0 12 8" aria-hidden><path d="M0 0 6 6 12 0"/></svg></OverlayArrow>}
      <PreviewContent isExiting={isExiting} title={title} titleId={titleId} label={label} onDismiss={dismiss}>{children}</PreviewContent>
      </>}
    </Popover>
  </PreviewTrigger>;
}

import type { CSSProperties } from 'react';
import { cx } from '@/utils/cx';

export type SpinnerProps = {
  size?: 'xs' | 'sm' | 'md' | 'lg';
  label?: string;
  className?: string;
  style?: CSSProperties;
};

/** Omit the label when a containing busy control already names the operation. */
export function Spinner({ size = 'md', label, className, style }: SpinnerProps) {
  return <span className={cx('ui-spinner', className)} data-size={size} role={label ? 'status' : undefined} aria-label={label} aria-hidden={!label || undefined} style={style}>
    <svg viewBox="0 0 24 24" fill="none" aria-hidden><circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="2" opacity=".18"/><path d="M12 3a9 9 0 0 1 9 9" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/></svg>
  </span>;
}

'use client';

import { useId, useState } from 'react';
import { RiArrowDownSLine, RiArrowRightUpLine, RiFileTextLine, RiGlobalLine } from '@remixicon/react';
import { Badge } from '@/components/base/badges/badge';
import { ButtonLink } from '@/components/base/buttons/button-link';
import { Collapsible } from '@/components/base/collapsible/collapsible';
import { HoverCard } from '@/components/base/hover-card/hover-card';
import { cx } from '@/utils/cx';
import { safeUrl, urlHostname } from '@/utils/safe-url';

export type Source = { id: string; title: string; url?: string; description?: string; publisher?: string; type?: 'web' | 'document'; date?: string; };
export type SourcesProps = { sources: Source[]; title?: string; defaultExpanded?: boolean; variant?: 'list' | 'grid'; className?: string; };

export function SourceCard({ source, index, compact = false }: { source: Source; index?: number; compact?: boolean }) {
  const url = safeUrl(source.url), publisher = source.publisher ?? urlHostname(url) ?? (source.type === 'document' ? 'Document' : 'Source');
  const Icon = source.type === 'document' ? RiFileTextLine : RiGlobalLine;
  return <article className="ui-source-card" data-compact={compact || undefined}>
    <div className="ui-source-card__meta"><span className="ui-source-card__publisher"><Icon size={14} aria-hidden/>{publisher}</span>{index != null && <Badge>{index}</Badge>}</div>
    <h4>{source.title}</h4>{source.description && <p>{source.description}</p>}
    {(source.date || url) && <div className="ui-source-card__footer">{source.date && <span>{source.date}</span>}{url && <ButtonLink href={url} target={/^https?:/.test(url) ? '_blank' : undefined} rel={/^https?:/.test(url) ? 'noopener noreferrer' : undefined} size="xs" variant="ghost" trailingIcon={RiArrowRightUpLine}>Open source</ButtonLink>}</div>}
  </article>;
}

export function InlineCitation({ source, index }: { source: Source; index: number }) {
  return <HoverCard trigger={<button type="button" className="ui-inline-citation" aria-label={`Source ${index}: ${source.title}`}><Badge variant="index">{index}</Badge></button>} label={`Source ${index}: ${source.title}`} placement="top">
    <SourceCard source={source} compact/>
  </HoverCard>;
}

export function Sources({ sources, title = 'Sources', defaultExpanded = true, variant = 'list', className }: SourcesProps) {
  const [open, setOpen] = useState(defaultExpanded), id = useId();
  return <section className={cx('ui-sources', className)} aria-label={title}>
    <button type="button" className="ui-sources__trigger" aria-expanded={open} aria-controls={id} onClick={() => setOpen(value => !value)}><RiGlobalLine size={16} aria-hidden/><span>{title}</span><Badge>{sources.length}</Badge><RiArrowDownSLine size={16} aria-hidden/></button>
    <Collapsible id={id} isOpen={open}><div className="ui-sources__items" data-variant={variant}>{sources.length ? sources.map((source,index)=><SourceCard source={source} key={source.id} index={index+1}/>) : <p className="ui-sources__empty">No sources are attached to this response.</p>}</div></Collapsible>
  </section>;
}

import { extendTailwindMerge } from 'tailwind-merge';

const typeFamilies = [
  'large-title', 'display-1', 'display-2', 'display-3', 'display-4',
  'title-1', 'title-2', 'title-3', 'headline', 'body', 'body-2',
  'caption-1', 'caption-2',
] as const;
const weights = ['regular', 'medium', 'semibold', 'bold'] as const;

// Custom text styles share Tailwind's text-* namespace with colors.
// Registering them keeps both classes when they appear together.
export const cx = extendTailwindMerge({
  extend: {
    classGroups: {
      'font-size': [{ text: typeFamilies.flatMap((family) => weights.map((weight) => `${family}-${weight}`)) }],
    },
  },
});

/** Permit web links and application paths without accepting script protocols. */
export function safeUrl(value: string | undefined): string | undefined {
  if (!value) return undefined;
  const trimmed = value.trim();
  if (/^https?:\/\//i.test(trimmed)) {
    try { return new URL(trimmed).href; } catch { return undefined; }
  }
  if (/^[\/#]/.test(trimmed) && !/^\/\//.test(trimmed) && !/[\u0000-\u001f\\]/.test(trimmed)) return trimmed;
  return undefined;
}

export function urlHostname(value: string | undefined) {
  try { return new URL(value ?? '').hostname.replace(/^www\./, ''); } catch { return undefined; }
}
